query GetReferenceElementsByExchangeId(
    $exchangeId: ID!
    $elementFilter: ElementFilterInput
    $elementPagination: PaginationInput
) {
    exchange(exchangeId: $exchangeId) {
        id
        name
        elements(filter: $elementFilter, pagination: $elementPagination) {
            pagination {
                pageSize
                cursor
            }
            results {
                id
                name
                properties(filter: { names: ["category", "type", "Element Name"] }) {
                    results {
                        name
                        value
                    }
                }
                references {
                    results {
                        name
                        value {
                            id
                            name
                            properties {
                                results {
                                    name
                                    value
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

